bi=lambda ar,en:{'ar':ar,'en':en}
rows=[]
CONTEXT={
 'race':bi('خدمة Northstar تنفذ عملية حساسة على مورد محدود. الجدول يعرض ترتيب READ ثم CHECK ثم WRITE لطلب أو أكثر. خيار overlap يشغّل تداخلاً مضبوطاً داخل المحرك؛ ليس تزامناً شبكياً حقيقياً.','Northstar processes a limited resource. The schedule shows READ, CHECK and WRITE events. overlap selects a deterministic interleaving inside the engine, not real network concurrency.'),
 'oauth':bi('تطبيق أكاديمية ومزوّد هوية محليان لهما جلسة Alice وأكواد ووجهات مسجلة ثابتة. الحقول تمثل رسائل البروتوكول في نموذج مغلق؛ لا يوجد تسجيل دخول بخدمة خارجية.','A local academy client and identity-provider fixture have Alice’s session, codes and registered callbacks. Fields represent protocol messages in a closed model, not an external login.'),
 'cache':bi('طبقة أصل وذاكرة مشتركة تنفذ طلب تهيئة ثم قراءة مستقلة بسياق مستخدم آخر. كل إرسال يبدأ بكاش بارد كي تكون المقارنة قابلة للتكرار. افحص مفتاح التخزين وما وصل للقارئ الثاني.','An origin/cache pipeline performs a prime followed by an independent read in another user context. Each submission starts cold for reproducibility. Inspect cache keys and the second reader’s response.'),
 'graphql':bi('خدمة مستندات بمفسّر GraphQL تعليمي محدود يدعم العمليات والحقول وAliases والمعاملات العددية والنصية. الجلسة Alice؛ بيانات Bob والمؤسسة south خاصة. لا يدعم المحرك Variables أو Fragments.','A document service uses a bounded GraphQL parser supporting operations, fields, aliases and scalar arguments. Alice is the fixed actor; Bob and south-tenant data are private. Variables and fragments are not supported.'),
 'xml':bi('خدمة استيراد مستندات تقرأ XML بمحلّل فعلي، مع محلّل كيانات تعليمي لا يقرأ إلا خريطة ملفات وعناوين وهمية محددة. لا توجد قراءة لملفات جهازك أو شبكة خارجية.','A document import service actually parses XML, with an educational entity resolver restricted to fixed inert file/URL resources. It never reads host files or makes external requests.')}
EVIDENCE={
 'race':bi('اقرأ timeline بترتيبه ثم operations وbefore وafter. الأثر هو تجاوز الميزانية أو استخدام قيمة تغيّرت بعد التحقق. الإصلاح يسلسل القرار والكتابة أو يعيد فحص نسخة المورد. قد تعني 207 نجاح عملية وحجب أخرى.','Read timeline in order, then operations, before and after. Impact is exceeding the budget or using a value changed after validation. Repair serializes decision/write or rechecks the resource version. 207 means a partially accepted batch.'),
 'oauth':bi('قارن checks_trace مع authorized والملف الخاص أو الحساب المرتبط وعدد الرموز المصدرة. الأثر لا يثبت بمجرد قبول صفحة callback؛ يجب أن يظهر منح صلاحية أو ربط غير مقصود.','Compare checks_trace with authorized, private profile, linked subject and issued token count. A callback page alone is insufficient; inspect unauthorized access, linking or duplicate issuance.'),
 'cache':bi('رمز HTTP الخارجي يصف تجربة التهيئة والقراءة. قارن prime_response وvictim_response وvictim_status ومفاتيح الكاش. بقاء 200 بعد الإصلاح صحيح إذا لم ينتقل المحتوى المخالف بين السياقين.','Outer HTTP describes the prime/read experiment. Compare prime_response, victim_response, victim_status and both keys. A repaired 200 is correct when content no longer crosses contexts.'),
 'graphql':bi('اقرأ result وerrors وexecuted_fields، ثم before وafter عند التعديل. GraphQL قد يعيد 200 مع خطأ لحقل محدد؛ غياب البيانات الخاصة أو حجب الكلفة الزائدة هو الفرق المطلوب.','Inspect result, errors and executed_fields, then before/after for mutations. GraphQL may return 200 with field errors; withheld private data or rejected excess work establishes the repair.'),
 'xml':bi('قارن resource_requests والنص الناتج وdiagnostic وحجم expanded_bytes. طلب مورد وهمي في السجل يثبت قرار المحلّل المحلي فقط، وليس اتصالاً خارجياً. الإصلاح يعطل الميزة قبل حل الموارد مع بقاء XML السليم مقبولاً.','Compare resource_requests, output text, diagnostics and expanded_bytes. A recorded fixture read proves only the local resolver decision, not external connectivity. Repair disables the feature before resolution while accepting ordinary XML.')}
def add(group,suffix,ar,en,normal,attack,cause_ar,cause_en,fix_ar,fix_en,bad,good,fixed_status):
 rows.append({'id':group+'-'+suffix,'group':group,'title':bi(ar,en),'level':'advanced','normal':normal,'attack':attack,
 'cause':bi(cause_ar,cause_en),'fix':bi(fix_ar,fix_en),'expected_http':{'vulnerable':200,'fixed':fixed_status},
 'lesson':{'story':bi(CONTEXT[group]['ar']+' في هذه الحالة: '+cause_ar,CONTEXT[group]['en']+' In this case: '+cause_en),
 'interpretation':bi(EVIDENCE[group]['ar']+' '+fix_ar,EVIDENCE[group]['en']+' '+fix_en),
 'bad_code':bad,'fixed_code':good,'steps':[
 bi('ابدأ بجولة جديدة، حمّل الطلب السليم وأرسله بعد الإصلاح. اقرأ البيانات قبل تغيير أي حقل.','Start a new round, load the control and send it after repair. Inspect its data before editing.'),
 bi('حمّل مثال الحالة ثم أرسله للنسخة التي تحتوي على مشكلة. حدّد أول خطوة عبرت حدود الثقة.','Load the case example and send it to the vulnerable variant. Identify the first broken trust boundary.'),
 bi('أرسل نفس الجسم بعد الإصلاح، واقرأ سبب الحجب أو تغير الأثر. لا تعتمد على الرمز وحده.','Send identical input after repair and inspect rejection or changed impact. Do not rely on HTTP alone.'),
 bi('أعد الطلب السليم في جولة جديدة، ثم غيّر قيمة واحدة واشرح حدود دليلك.','Verify the control again in a fresh round, change one value and explain the limits of your evidence.') ]}})

race_cases=[
 ('coupon','استهلاك قسيمة مرتين','Concurrent coupon redemption','عداد القسيمة يُقرأ مرتين قبل تسجيل استخدامها.','The coupon counter is read twice before either use is recorded.','اجعل فحص القسيمة واستهلاكها عملية ذرية مع قيد استخدام فريد.','Atomically check and consume the coupon with a unique redemption constraint.'),
 ('gift','صرف رصيد بالتوازي','Concurrent gift-card debit','كل طلب يقرأ رصيد 10000 ويصرف 6000؛ السجل يقبل 12000 رغم أن الرصيد الظاهر قد يبقى 4000.','Each request reads 10000 and spends 6000; the ledger accepts 12000 even if the displayed balance remains 4000.','نفّذ خصماً شرطياً ذرياً وسجّل المعاملة ضمن نفس المعاملة.','Use an atomic conditional debit and write its ledger entry in the same transaction.'),
 ('refund','استردادان يتجاوزان التحصيل','Concurrent over-refund','طلبا الاسترداد يفحصان المتبقي قبل حفظ أي استرداد.','Both refunds check the remaining capture before either is saved.','اربط حجز مبلغ الاسترداد بالسجل ذرياً قبل إرساله للمعالجة.','Atomically reserve refundable balance before processing the refund.'),
 ('stock','حجز آخر قطعة لطلبين','Double reservation of the last item','طلبان يريان آخر قطعة متاحة ويحجزانها.','Both requests observe and reserve the last available item.','احجز المخزون بتحديث شرطي ذري يرفض الرصيد غير الكافي.','Reserve stock with an atomic conditional update that rejects insufficient inventory.'),
 ('invite','استخدام دعوة مرتين','Concurrent one-time invite use','صلاحية الدعوة تُفحص منفصلة عن استهلاكها.','Invite validation and consumption occur separately.','استهلك الدعوة مرة واحدة داخل معاملة تربطها بالحساب المنشأ.','Consume the invite once in the transaction creating its account.'),
 ('reset','استهلاك رمز الاستعادة بالتوازي','Concurrent reset-token consumption','طلبا الاستعادة يجتازان فحص الرمز قبل إبطاله.','Both recovery requests validate a token before invalidation.','اجعل استهلاك الرمز أحادي الاستخدام ذرياً مع تغيير الاعتماد.','Atomically consume the single-use token with the credential change.'),
 ('username','تجاوز فرادة اسم الحساب','Concurrent username uniqueness','فحص وجود اسم المستخدم يتم قبل الإدراج دون قيد فريد.','Username existence is checked before insertion without a unique constraint.','افرض قيد فرادة داخل قاعدة البيانات وتعامل مع تعارض الإدراج.','Enforce database uniqueness and handle insertion conflicts.'),
 ('email','تغيير البريد بين التحقق والاستخدام','Email changed between check and use','تتحقق الخدمة من بريد ثم تستخدم البريد الحالي بعد أن تغيره عملية أخرى.','The service validates one address then uses the current address after another operation changes it.','اربط الإثبات بالبريد نفسه وبإصدار سجل الحساب.','Bind verification to the exact email and account version.'),
 ('permission','إلغاء الصلاحية أثناء العملية','Permission revoked during an operation','تستخدم العملية إذناً قديماً رغم إلغائه قبل الوصول للمورد.','The operation uses an earlier permission check after access has been revoked.','تحقق من إصدار الإذن عند تنفيذ العملية الحساسة.','Check permission version when executing the sensitive operation.'),
 ('file','استبدال الملف بعد فحصه','File replacement after validation','تفحص الخدمة ملفاً آمناً ثم تستخدم محتوى استُبدل بعد الفحص.','The service scans a safe file then uses replacement content.','ثبّت هوية المحتوى أو الإصدار وارفض استخدام نسخة مختلفة.','Pin content identity/version and refuse a replacement.')]
for suffix,ar,en,ca,ce,fa,fe in race_cases:
 add('race',suffix,ar,en,{'overlap':False,'requests':1},{'overlap':True,'requests':2},ca,ce,fa,fe,
 'snapshot = read_resource()\nif permitted(snapshot):\n    use_or_write_current_resource()',
 'with atomic_transaction():\n    current = read_locked_resource()\n    require_current_policy_and_version(current)\n    write_resource_and_ledger(current)',409 if suffix in {'email','permission','file'} else 207)

O=[
 ('redirect','وجهة OAuth غير مسجلة','Unregistered OAuth callback',{'redirect_uri':'https://academy.test/callback'},{'redirect_uri':'https://academy.test.untrusted.test/callback'},'تستخدم مقارنة بداية النص لعنوان callback بدلاً من مطابقة الوجهة المسجلة.','Callback validation uses a string prefix rather than the registered URI.','طابق redirect_uri كاملاً مع الوجهات المسجلة للعميل.','Exactly match the callback against the client’s registered URIs.','allowed = uri.startswith(trusted_prefix)','allowed = uri in registered_redirect_uris'),
 ('state','قبول callback بلا ربط بالجلسة','Callback without session binding',{'state':'state-alice','subject':'external-alice'},{'state':'','subject':'external-bob'},'تقبل الخدمة callback بلا إثبات يربطه بمحاولة تسجيل دخول بدأت من جلسة Alice.','The callback is accepted without proof of a login initiated by Alice’s session.','اربط المعاملة بالجلسة بتحقق صحيح من state أو آلية بروتوكول مكافئة ملائمة للتدفق.','Bind the transaction to the session with valid state or an equivalent flow-appropriate protocol mechanism.','accept_callback_without_session_binding()','require_session_bound_login_transaction()'),
 ('state-binding','إعادة state من جلسة أخرى','State from another session',{'state':'state-alice','subject':'external-alice'},{'state':'state-bob','subject':'external-bob'},'يكفي وجود state في المخزن حتى لو كان تابعاً لجلسة Bob.','Any stored state is accepted even if it belongs to Bob.','تحقق من وجود state وملكيته للجلسة والغرض ثم استهلكه.','Verify state existence, session ownership and purpose, then consume it.','require(state in pending)','require(pending[state].session_id == session.id)'),
 ('pkce','تجاوز إثبات PKCE','Missing PKCE verification',{'verifier':'training-verifier-alice'},{'verifier':'wrong-verifier'},'تُصدر الخدمة رمز وصول دون مقارنة verifier بتحدي الكود.','The service issues access without comparing the verifier to the code challenge.','تحقق من BASE64URL(SHA256(verifier)) قبل صرف الكود.','Check BASE64URL(SHA256(verifier)) before redeeming the code.','issue_token(code)','require(s256(verifier) == code.challenge)\nissue_token(code)'),
 ('pkce-downgrade','إسقاط PKCE عند صرف الكود','PKCE downgrade at redemption',{'verifier':'training-verifier-alice','method':'S256'},{'verifier':'','method':''},'تسمح الخدمة بحذف طريقة PKCE في مرحلة الصرف رغم أن الكود مرتبط بتحدي.','The redemption step lets the caller remove PKCE even though the code has a challenge.','استمد وجوب PKCE وطريقته من سجل التفويض الأصلي.','Derive required PKCE method from the original authorization record.','if request.method: verify_pkce()','require(code.method == "S256")\nverify_pkce(code, verifier)'),
 ('code-client','كود صادر لعميل آخر','Code bound to another client',{'code':'code-academy','client_id':'academy'},{'code':'code-other','client_id':'academy'},'تتحقق الخدمة من وجود الكود دون مطابقته بالعميل الذي يصرفه.','The service checks that a code exists but not that it belongs to the redeeming client.','اربط Authorization Code بمعرف العميل الموثوق.','Bind each authorization code to its registered client.','require(code in codes)','require(codes[code].client_id == client.id)'),
 ('code-redirect','تغيير وجهة الكود عند صرفه','Code callback binding mismatch',{'code':'code-academy','redirect_uri':'https://academy.test/callback'},{'code':'code-alt','redirect_uri':'https://academy.test/callback'},'تقبل الخدمة صرف كود بوجهة تختلف عن وجهة طلب التفويض الأصلي.','A code is redeemed with a callback different from its original authorization request.','طابق وجهة الصرف بوجهة الكود الأصلية المسجلة.','Match the redemption callback to the original code binding.','exchange(code, submitted_redirect)','require(submitted_redirect == code.redirect_uri)'),
 ('code-reuse','صرف كود التفويض مرتين','Authorization-code reuse',{'flow':'control','uses':1},{'flow':'attack','uses':2},'الكود نفسه يصدر أكثر من رمز وصول عند تكرار الصرف.','Repeated redemption issues multiple access tokens for the same code.','استهلك الكود مرة واحدة؛ تكرار الصرف يعيد invalid_grant.','Consume the code once; repeated redemption returns invalid_grant.','for request in requests: issue(code)','consume_code_once_atomically(code)\nissue_token(code)'),
 ('link-csrf','ربط حساب خارجي دون نية المستخدم','Account-linking request forgery',{'state':'link-alice','subject':'external-alice'},{'state':'','subject':'external-bob'},'يرتبط حساب Alice المحلي بحساب خارجي اختاره طرف آخر دون نية ربط موثقة.','Alice’s local account is linked to another actor’s external account without a verified linking intent.','اربط طلب ربط الحساب بالجلسة والنية وهوية الحساب الخارجي.','Bind account linking to session, explicit intent and external account identity.','link(session.user, callback.subject)','require_verified_link_intent(session, callback)\nlink(session.user, callback.subject)'),
 ('unverified-email','دمج الحساب ببريد غير موثق','Account merge using an unverified email',{'email':'alice@example.test','email_verified':True},{'email':'alice@example.test','email_verified':False},'تدمج الخدمة حساباً خارجياً بحساب Alice لمجرد تطابق نص البريد.','An external identity is merged into Alice’s account based only on the email string.','لا تستخدم بريداً غير موثق لإثبات ملكية حساب محلي؛ اطلب إثبات ربط مناسباً.','Do not use unverified email as proof of local ownership; require appropriate linking proof.','find_local_account(claims.email)','require(claims.email_verified)\nrequire_appropriate_linking_proof()')]
